// Fails when a source file lacks the Apache-2.0 header, like Spotless does for the Kotlin code (PLAN §14.3).
// `worker-configuration.d.ts` is generated by `wrangler types` and exempt.

import { readdirSync, readFileSync, statSync } from "node:fs";
import { join, relative } from "node:path";

const HEADER = "/*\n * Copyright 2026 The MediaSync Authors\n * SPDX-License-Identifier: Apache-2.0\n */\n";
const root = new URL("..", import.meta.url).pathname;
const roots = ["src", "test", "scripts", "vitest.config.ts"];

function* sources(path) {
    if (statSync(path).isDirectory()) {
        for (const entry of readdirSync(path)) yield* sources(join(path, entry));
    } else if (/\.(ts|mjs)$/.test(path)) {
        yield path;
    }
}

const missing = roots
    .flatMap((entry) => [...sources(join(root, entry))])
    .filter((file) => !readFileSync(file, "utf8").startsWith(HEADER))
    .map((file) => relative(root, file));

if (missing.length > 0) {
    console.error(`Missing the license header:\n${missing.map((file) => `  ${file}`).join("\n")}`);
    process.exit(1);
}
console.log("License headers: OK");
